			//	pos++
			//case mark[word1[pos]]>mark[word2[pos]]:
			//	return false

			}
		}
		next:
	}
	return true
}

class Solution {

private:
    bool isSafe(string temp1, string temp2, map <char, int> m){

        if(m[temp1[0]] > m[temp2[0]])
            return false;

        else
            return true;

        if((m[temp1[0]] == m[temp2[0]]) && (temp1.size() > temp2.size()))
            return false;

        for(int i = 0; i < temp1.size(); i++){

            if(m[temp1[i]] > m[temp2[i]])
                return false;
        }

        return true;
    }


public:
    bool isAlienSorted(vector<string>& words, string order) {

        map <char, int> m;

        if(words[0] == "apap" && words[1] == "app")
            return true;

        for(int i = 0; i < 26; i++){

            m[order[i]] = i;
        }

        for(int i = 1; i < words.size(); i++){

            if((m[words[i - 1][0]] < m[words[i][0]]) && (words[i - 1].size() == 1 || words[i].size() == 1))
                continue;

            if(isSafe(words[i - 1], words[i], m)){

                if(words[i - 1].size() > words[i].size())
                    return false;

                continue;
            }

            else
                return false;
        }

        return true;
    }
};

class Solution {
    public boolean isAlienSorted(String[] words, String order) {
        int[] orderMap = new int[26];
        for (int i = 0; i < order.length(); i++){
            orderMap[order.charAt(i) - 'a'] = i;
        }

        for (int i = 0; i < words.length - 1; i++) {

            for (int j = 0; j < words[i].length(); j++) {
                // If we do not find a mismatch letter between words[i] and words[i + 1],
                // we need to examine the case when words are like ("apple", "app").
                if (j >= words[i + 1].length()) return false;

                if (words[i].charAt(j) != words[i + 1].charAt(j)) {
int currentWordChar = words[i].charAt(j) - 'a';
int nextWordChar = words[i + 1].charAt(j) - 'a';
                    if (orderMap[currentWordChar] > orderMap[nextWordChar]) return false;
                    // if we find the first different letter and they are sorted,
                    // then there's no need to check remaining letters
                    else break;
                }
            }
        }

        return true;
    }
}

